mapper.select:
SELECT ctrl_cmd_status_change_id, request_control_command_id, status_update_time, change_status, status_result_msg FROM msa_control_command_status_change_record where 1=1
and ctrl_cmd_status_change_id = #{ctrlCmdStatusChangeId}
and request_control_command_id = #{requestControlCommandId}
order by ctrl_cmd_status_change_id desc

mapper.update:

  UPDATE msa_control_command_status_change_record
	SET

	request_control_command_id = #{requestControlCommandId},


	status_update_time = NOW(3),


	change_status = #{changeStatus},


	status_result_msg = #{statusResultMsg}

	WHERE
	  ctrl_cmd_status_change_id = #{ctrlCmdStatusChangeId}
	          AND request_control_command_id = #{requestControlCommandId}

